"I am developing a high-frequency paranormal sensor HUD called NULL_VEC_CORE_11.4. I need you to take the provided base code and perform a full architectural upgrade based on these forensic requirements. Maintain the Indigo/Cyan/Amber tactical aesthetic (Blue GUI).
REQUIRED UPGRADES:
Instructional Info Overlay:
Create a hidden div overlay that triggers when tapping the header: '\u25a0 LATTICE_ANOMALY_DETECTOR [INFO]'.
It must display clear instructions for: DE-SENSE (stabilizing thresholds), MUTE_EVP (audio focus safety), and MUTE_SAGE (voice personality).
Sarcasm Personality Matrix:
Implement an array of strings: ["DIMENSIONAL_MEMBRANE_THINNING", "SIGNAL_ANOMALY_OR_WISHFUL_THINKING", "ENTROPY_IS_TALKING_AGAIN", "LATTICE_ITCH_DETECTED", "11.3_DEVIATION_SPOTTED"].
Add a SARCASM_MATRIX toggle switch in the footer.
If ON: Alerts pull randomly from the array.
If OFF: Alerts default to 'ANOMALY_DETECTED'.
Hard-Kill Audio Mute:
The [MUTE_EVP] button must physically iterate through stream.getAudioTracks() and set enabled = false.
This is critical to prevent AUDIOFOCUS conflicts with other LLM nodes.
Visual Feedback: When Muted, the button border and text must turn Amber (#ff9f1c).
De-Sense Stabilizer Logic:
Add a toggle that, when active, multiplies the sensitivity threshold by 3.5x.
This filters out 'Human Noise' like walking or breathing while keeping the sensor loop active.
Enhanced System Log:
The log should be scrollable and timestamp every event, including when the Stabilizer is toggled or the Mic is killed."
I want to keep this interface as much as possible
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>NULL_VEC_CORE_11.3</title>
<style>
body { background: #02040a; color: #70d6ff; font-family: 'Courier New', monospace; margin: 0; overflow: hidden; }
#top-bar { padding: 10px; border-bottom: 1px solid #1a2a44; font-size: 10px; display: flex; justify-content: space-between; background: #02040a; }
.module { margin: 10px; border: 1px solid #1a2a44; background: rgba(10,15,28,0.8); position: relative; }
.module-header { padding: 8px; background: #0d1117; font-size: 10px; color: #70d6ff; border-bottom: 1px solid #1a2a44; cursor: help; }
/* Mag Delta Display */
#mag-display { position: absolute; top: 40px; right: 20px; text-align: right; }
#magnitude { font-size: 4.5rem; margin: 0; color: #70d6ff; text-shadow: 0 0 15px rgba(112,214,255,0.6); }
/* Audio Waterfall */
#evp-area { height: 180px; position: relative; border-top: 1px solid #1a2a44; }
#waterfall { width: 100%; height: 100%; opacity: 0.8; }
/* Info Overlay */
#info-overlay { position: fixed; top: 20%; left: 10%; width: 80%; background: #05070c; border: 1px solid #ff9f1c; padding: 15px; z-index: 100; display: none; font-size: 11px; color: #ff9f1c; box-shadow: 0 0 20px #000; }
/* Control Deck */
#footer { position: fixed; bottom: 0; width: 100%; padding: 12px; background: #05070c; border-top: 2px solid #1a2a44; }
.control-row { display: flex; gap: 8px; margin-bottom: 8px; }
.btn { flex: 1; border: 1px solid #70d6ff; background: transparent; color: #70d6ff; padding: 12px; font-size: 10px; text-transform: uppercase; }
.btn.active-warn { border-color: #ff9f1c; color: #ff9f1c; background: rgba(255,159,28,0.1); }
#log { font-size: 10px; color: #4cc9f0; height: 45px; overflow: hidden; border-top: 1px solid #1a2a44; margin-top: 8px; padding-top: 5px; }
/* Stabilizer Toggle */
.switch-row { display: flex; justify-content: space-between; align-items: center; padding: 5px 0; font-size: 10px; }
</style>
</head>
<body>
<div id="info-overlay" onclick="this.style.display='none'">
<b style="font-size: 13px;">CORE_ADJUSTMENT_LOGIC:</b><br><br>
- <b>DE-SENSE:</b> Triples threshold. Prevents "Sarcasm Spikes" during physical movement.<br>
- <b>MUTE_EVP:</b> Hard-kills the mic stream. MUST be ON to talk to Sage/AI without "Retry" errors.<br>
- <b>MUTE_SAGE:</b> Disables text-to-speech output.<br><br>
[TAP TO CLOSE]
</div>
<div id="top-bar">
<span>NODE: SAGE_CORE_11.3</span>
<span id="clock">00:00:00</span>
</div>
<div class="module">
<div class="module-header" onclick="document.getElementById('info-overlay').style.display='block'">\u25a0 LATTICE_ANOMALY_DETECTOR [INFO]</div>
<div style="height: 180px; position: relative;">
<canvas id="emf-wave"></canvas>
<div id="mag-display">
<h1 id="magnitude">0.00</h1>
<span style="font-size: 9px; opacity: 0.5;">MAG_DELTA (\u03bcT)</span>
</div>
</div>
<div id="evp-area">
<canvas id="waterfall"></canvas>
</div>
</div>
<div id="footer">
<div class="switch-row">
<span>DE-SENSE (STABILIZER)</span>
<input type="checkbox" onchange="toggleDeSense(this.checked)" style="transform: scale(1.5);">
</div>
<div class="control-row">
<button id="btn-sage" class="btn" onclick="toggleSageVoice()">[MUTE_SAGE]</button>
<button id="btn-evp" class="btn" onclick="toggleEVPMic()">[MUTE_EVP]</button>
</div>
<div class="control-row">
<button class="btn" onclick="initSensors()">[INIT_LATTICE]</button>
<button class="btn" onclick="toggleEVP()">[BURST_RECORD]</button>
<button class="btn" onclick="markEvent()">[MARK]</button>
</div>
<div id="log">> STANDBY...</div>
</div>
<script>
var stream, audioCtx, analyser, dataArray, waterfallCanvas, waterfallCtx, emfCanvas, emfCtx;
var baseline = null, magHistory = [], lastAlert = 0, sensorsActive = false;
var deSenseMode = false, isMutedSFX = false, isEVPMuted = false;
var sarcasm = ["DIMENSIONAL_MEMBRANE_THINNING", "SIGNAL_ANOMALY_OR_WISHFUL_THINKING", "ENTROPY_IS_TALKING_AGAIN"];
function talk(t) {
if (isMutedSFX || !window.speechSynthesis) return;
window.speechSynthesis.cancel();
let u = new SpeechSynthesisUtterance(t.replace(/_/g, " "));
u.pitch = 0.7; u.rate = 0.9;
window.speechSynthesis.speak(u);
}
function toggleDeSense(v) {
deSenseMode = v;
updateLog(v ? "STABILIZER: ACTIVE" : "STABILIZER: RAW");
talk(v ? "Stabilizer On" : "Stabilizer Off");
}
function toggleSageVoice() {
isMutedSFX = !isMutedSFX;
document.getElementById('btn-sage').classList.toggle('active-warn', isMutedSFX);
}
function toggleEVPMic() {
if (!stream) return;
isEVPMuted = !isEVPMuted;
// Hard-toggle the track
stream.getAudioTracks().forEach(t => t.enabled = !isEVPMuted);
document.getElementById('btn-evp').classList.toggle('active-warn', isEVPMuted);
updateLog(isEVPMuted ? "MIC_KILLED" : "MIC_LIVE");
talk(isEVPMuted ? "Microphone Deactivated" : "Microphone Live");
}
function updateLog(m) {
let l = document.getElementById("log");
l.innerHTML = "> " + m + "<br>" + l.innerHTML.split("<br>").slice(0, 2).join("<br>");
}
async function initSensors() {
if (sensorsActive) return;
try {
stream = await navigator.mediaDevices.getUserMedia({ audio: true });
audioCtx = new (window.AudioContext || window.webkitAudioContext)();
analyser = audioCtx.createAnalyser();
audioCtx.createMediaStreamSource(stream).connect(analyser);
analyser.fftSize = 256;
dataArray = new Uint8Array(analyser.frequencyBinCount);
waterfallCanvas = document.getElementById("waterfall"); waterfallCtx = waterfallCanvas.getContext("2d");
emfCanvas = document.getElementById("emf-wave"); emfCtx = emfCanvas.getContext("2d");
window.addEventListener("devicemotion", (e) => {
let acc = e.accelerationIncludingGravity;
if (!acc) return;
let mag = Math.sqrt(acc.x**2 + acc.y**2 + acc.z**2);
if (baseline === null) baseline = mag;
document.getElementById("magnitude").innerText = mag.toFixed(2);
magHistory.push(mag); if(magHistory.length > 60) magHistory.shift();
let delta = Math.abs(mag - baseline);
let thresh = deSenseMode ? 4.0 : 1.2;
if (delta > thresh && (Date.now() - lastAlert > 2000)) {
let msg = sarcasm[Math.floor(Math.random() * sarcasm.length)];
updateLog(msg); talk(msg);
lastAlert = Date.now();
}
});
sensorsActive = true;
resize();
draw();
talk("Lattice Connected");
} catch (e) { updateLog("ERR: ACCESS_DENIED"); }
}
function resize() {
waterfallCanvas.width = window.innerWidth - 20; waterfallCanvas.height = 180;
emfCanvas.width = window.innerWidth - 20; emfCanvas.height = 120;
}
function draw() {
requestAnimationFrame(draw);
// Audio Waterfall
analyser.getByteFrequencyData(dataArray);
let img = waterfallCtx.getImageData(0, 0, waterfallCanvas.width, waterfallCanvas.height);
waterfallCtx.putImageData(img, 0, 2);
for (let i = 0; i < dataArray.length; i++) {
waterfallCtx.fillStyle = `rgba(112, 214, 255, ${dataArray[i]/255})`;
waterfallCtx.fillRect(i * (waterfallCanvas.width/dataArray.length), 0, 2, 2);
}
// EMF Wave
emfCtx.clearRect(0,0,emfCanvas.width,emfCanvas.height);
emfCtx.beginPath(); emfCtx.strokeStyle = "#70d6ff";
magHistory.forEach((m, i) => {
let x = i * (emfCanvas.width/60);
let y = 60 - (m - baseline) * 20;
if(i==0) emfCtx.moveTo(x,y); else emfCtx.lineTo(x,y);
});
emfCtx.stroke();
}
function markEvent() { updateLog("EVENT_MARKED"); talk("Marked"); }
setInterval(() => { document.getElementById("clock").innerText = new Date().toLocaleTimeString(); }, 1000);
</script>
</body>
</html>
